# lote-acervo.tf -- o que E declaravel: buckets de entrada/saida e a
# tabela de controle de progresso por fatia. O fatiamento em si e codigo.

resource "aws_s3_bucket" "lote_entrada" {
  bucket = "${var.projeto}-lote-acervo-entrada"
}

resource "aws_s3_bucket" "lote_saida" {
  bucket = "${var.projeto}-lote-acervo-saida"
}

resource "aws_s3_bucket_lifecycle_configuration" "lote_entrada" {
  bucket = aws_s3_bucket.lote_entrada.id
  rule {
    id     = "expirar-manifesto-processado"
    status = "Enabled"
    # 14 dias bastam para investigar uma fatia com problema antes do
    # manifesto de entrada sumir -- o resultado fica no bucket de saida,
    # que tem regra propria e mais longa.
    expiration { days = 14 }
  }
}

# Uma linha por fatia: status, ARN do job quando existir, contagem de
# itens, custo estimado e timestamps. E o que falta no laco sincrono da
# arquitetura minima -- sem isso, uma falha no meio perde o progresso.
resource "aws_dynamodb_table" "controle_fatias" {
  name         = "${var.projeto}-controle-fatias-acervo"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "fatia_id"

  attribute {
    name = "fatia_id"
    type = "S"
  }
}

data "aws_iam_policy_document" "confianca_lambda" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "fatiar_catalogo" {
  name               = "${var.projeto}-fatiar-catalogo"
  assume_role_policy = data.aws_iam_policy_document.confianca_lambda.json
}

data "aws_iam_policy_document" "fatiar_catalogo" {
  statement {
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.lote_entrada.arn}/*"]
  }
  statement {
    effect    = "Allow"
    actions   = ["dynamodb:PutItem", "dynamodb:UpdateItem"]
    resources = [aws_dynamodb_table.controle_fatias.arn]
  }
}

resource "aws_iam_role_policy" "fatiar_catalogo" {
  role   = aws_iam_role.fatiar_catalogo.id
  policy = data.aws_iam_policy_document.fatiar_catalogo.json
}

// FatiarCatalogo.cs -- le o catalogo de origem, grava um manifesto por
// fatia de 50 mil itens, e inicializa o controle de progresso. Roda uma
// vez por execucao do lote inteiro, disparada pela maquina de estados.

public sealed class FatiarCatalogo
{
    private const int TamanhoFatia = 50_000;
    private readonly IAmazonS3 _s3;
    private readonly IAmazonDynamoDB _ddb;
    private readonly string _bucketEntrada;
    private readonly string _tabelaControle;

    public async Task<int> ExecutarAsync(CancellationToken ct)
    {
        var itens = await CarregarCatalogoAsync(ct); // 2.000.000 itens, origem: catalogo de producao
        var totalFatias = (int)Math.Ceiling(itens.Count / (double)TamanhoFatia);

        for (var i = 0; i < totalFatias; i++)
        {
            var fatiaId = $"fatia-{i:D3}";
            var pagina = itens.Skip(i * TamanhoFatia).Take(TamanhoFatia);

            // So grava manifesto e cria o registro se a fatia AINDA NAO existe
            // no controle -- reexecutar este fatiamento nao duplica fatia
            // nem reseta o progresso de uma que ja esta em andamento.
            var jaExiste = await _ddb.GetItemAsync(new GetItemRequest
            {
                TableName = _tabelaControle,
                Key = new() { ["fatia_id"] = new AttributeValue { S = fatiaId } },
            }, ct);
            if (jaExiste.Item.Count > 0) continue;

            await GravarManifestoAsync(fatiaId, pagina, ct);

            await _ddb.PutItemAsync(new PutItemRequest
            {
                TableName = _tabelaControle,
                Item = new()
                {
                    ["fatia_id"] = new AttributeValue { S = fatiaId },
                    ["status"] = new AttributeValue { S = "pendente" },
                    ["itens"] = new AttributeValue { N = pagina.Count().ToString() },
                    ["criada_em"] = new AttributeValue { S = DateTimeOffset.UtcNow.ToString("o") },
                },
            }, ct);
        }
        return totalFatias; // 40, para os 2 milhoes de itens atuais
    }
}

# orquestracao-lote.tf -- agendador dispara a maquina de estados de
# madrugada; a maquina fatia, dispara e monitora, sem reprocessar fatia
# concluida.

resource "aws_scheduler_schedule" "disparar_lote_acervo" {
  name       = "${var.projeto}-disparar-lote-acervo"
  group_name = "default"

  flexible_time_window { mode = "OFF" }
  # 2h da manha -- fora do horario comercial, folga suficiente para o
  # lote terminar (medido em ~17h corridas) antes do proximo horario
  # de pico de trafego interativo.
  schedule_expression          = "cron(0 2 * * ? *)"
  schedule_expression_timezone = "America/Sao_Paulo"

  target {
    arn      = aws_sfn_state_machine.lote_acervo.arn
    role_arn = aws_iam_role.scheduler_invoca_sfn.arn
  }
}

resource "aws_sfn_state_machine" "lote_acervo" {
  name     = "${var.projeto}-lote-acervo"
  role_arn = aws_iam_role.execucao_sfn.arn
  definition = jsonencode({
    Comment = "Fatia o acervo pendente, dispara jobs de lote, monitora e retoma"
    StartAt = "ListarFatiasPendentes"
    States = {
      ListarFatiasPendentes = {
        Type     = "Task"
        Resource = aws_lambda_function.listar_pendentes.arn
        Next     = "ProcessarFatias"
      }
      # Map com concorrencia limitada -- ate 12 fatias ao mesmo tempo,
      # dentro da cota de jobs de lote concorrentes da conta (confira o
      # valor atual em Service Quotas antes de ajustar este numero).
      ProcessarFatias = {
        Type           = "Map"
        ItemsPath      = "$.fatiasPendentes"
        MaxConcurrency = 12
        Iterator = {
          StartAt = "DispararJobLote"
          States = {
            DispararJobLote = {
              Type     = "Task"
              Resource = aws_lambda_function.disparar_job_lote.arn
              Next     = "AguardarJob"
            }
            AguardarJob = { Type = "Wait", Seconds = 900, Next = "VerificarStatus" }
            VerificarStatus = {
              Type     = "Task"
              Resource = aws_lambda_function.verificar_status_job.arn
              Next     = "JobConcluido"
            }
            JobConcluido = {
              Type = "Choice"
              Choices = [
                { Variable = "$.status", StringEquals = "concluida", Next = "Fim" },
                { Variable = "$.status", StringEquals = "falhou", Next = "Fim" },
              ]
              Default = "AguardarJob"
            }
            Fim = { Type = "Succeed" }
          }
        }
        End = true
      }
    }
  })
}

// DispararJobLote.cs -- para UMA fatia, checa o controle de progresso e,
// se ainda nao esta em andamento nem concluida, cria o job de lote.
// Checar antes de disparar e o que evita pagar duas vezes pela mesma
// fatia se a maquina de estados reexecutar este passo.

public async Task<ResultadoDisparo> ExecutarAsync(string fatiaId, CancellationToken ct)
{
    var registro = await _ddb.GetItemAsync(new GetItemRequest
    {
        TableName = _tabelaControle,
        Key = new() { ["fatia_id"] = new AttributeValue { S = fatiaId } },
    }, ct);

    var status = registro.Item.GetValueOrDefault("status")?.S;
    if (status is "em_andamento" or "concluida")
    {
        _logger.LogInformation("{Fatia} ja esta {Status}; nao disparando job novo", fatiaId, status);
        return new ResultadoDisparo(fatiaId, status, JobArn: registro.Item.GetValueOrDefault("job_arn")?.S);
    }

    var job = await _bedrock.CreateModelInvocationJobAsync(new CreateModelInvocationJobRequest
    {
        JobName   = $"enriquecimento-acervo-{fatiaId}-{DateTime.UtcNow:yyyyMMddHHmm}",
        ModelId   = "anthropic.claude-haiku-4-5-...", // classificacao curta, modelo leve tambem no lote
        RoleArn   = _roleArnBedrockBatch,
        InputDataConfig  = new() { S3InputDataConfig  = new() { S3Uri = $"s3://{_bucketEntrada}/{fatiaId}.jsonl" } },
        OutputDataConfig = new() { S3OutputDataConfig = new() { S3Uri = $"s3://{_bucketSaida}/{fatiaId}/" } },
    }, ct);

    // Escrita condicional: falha se outra execucao concorrente ja marcou
    // esta fatia como em_andamento entre o GetItem acima e este PutItem --
    // e a corrida que este desenho existe para evitar.
    await _ddb.PutItemAsync(new PutItemRequest
    {
        TableName           = _tabelaControle,
        Item                = new()
        {
            ["fatia_id"]   = new AttributeValue { S = fatiaId },
            ["status"]     = new AttributeValue { S = "em_andamento" },
            ["job_arn"]    = new AttributeValue { S = job.JobArn },
            ["disparada_em"] = new AttributeValue { S = DateTimeOffset.UtcNow.ToString("o") },
        },
        ConditionExpression = "attribute_not_exists(job_arn) OR #s <> :em_andamento",
        ExpressionAttributeNames  = new() { ["#s"] = "status" },
        ExpressionAttributeValues = new() { [":em_andamento"] = new AttributeValue { S = "em_andamento" } },
    }, ct);

    return new ResultadoDisparo(fatiaId, "em_andamento", job.JobArn);
}

# auditoria-athena.tf -- tabela externa sobre o resultado do lote, e um
# workgroup dedicado para nao misturar o custo de consulta deste modulo
# com o de outras cargas de Athena da conta.

resource "aws_glue_catalog_database" "acervo" {
  name = "${var.projeto}_acervo_classificado"
}

resource "aws_glue_catalog_table" "resultado_lote" {
  name          = "resultado_lote"
  database_name = aws_glue_catalog_database.acervo.name
  table_type    = "EXTERNAL_TABLE"

  storage_descriptor {
    location      = "s3://${aws_s3_bucket.lote_saida.bucket}/"
    input_format  = "org.apache.hadoop.mapred.TextInputFormat"
    output_format = "org.apache.hadoop.hive.ql.io.HiveIgnoreKeyTextOutputFormat"

    ser_de_info {
      serialization_library = "org.openx.data.jsonserde.JsonSerDe"
    }

    columns {
      name = "record_id"
      type = "string"
    }
    columns {
      name = "categoria"
      type = "string"
    }
    columns {
      name = "atributo"
      type = "string"
    }
    columns {
      name = "palavras_chave"
      type = "array<string>"
    }
  }
}

resource "aws_athena_workgroup" "auditoria_acervo" {
  name = "${var.projeto}-auditoria-acervo"

  configuration {
    result_configuration {
      output_location = "s3://${aws_s3_bucket.lote_saida.bucket}/_resultados-athena/"
    }
  }
}
